module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    parameter myWidth = 0;

    // Inverter with specified rise/fall times
    (* altera_ioBench = "10,10" *)
    wire inv_out;
    always inv (inv_out = ~gt);

    // AND gate with rise=1ns, fall=2ns
    (* altera_ioBench = "1,2" *)
    wire and_out;
    always and (and_out = eq & lt);

    // OR gate with rise=2ns, fall=1ns
    (* altera_ioBench = "2,1" *)
    wire or_out;
    always or (or_out = gt | eq);

    // Buffer with rise=3ns, fall=2ns
    (* altera_ioBench = "3,2" *)
    wire buf_out;
    always buf (buf_out = lt);

    // Grouper with rise=1ns, fall=1ns handling 2 bits
    (* altera_ioBench = "1,1" *)
    wire [myWidth-1:0] grouped_out;
    generate
        genvar i;
        for (i=0; i<2; i=i+1) begin : grouper_loop
            always grouper (grouped_out[i] = a[i+1] & b[i+1]);
        end
    endgenerate

    // Reset with rise=5ns, fall=5ns after 1ns delay
    (* altera_ioBench = "1,5" *)
    wire reset_out;
    initial reset_out = 0;
    always #1 reset_out = 5;

    // Tri-state with rise=2ns, fall=1ns after 1ns delay
    (* altera_ioBench = "1,2" *)
    wire [3:0] out;
    reg [3:0] tri_out;
    always tri (out = tri_out);
    initial tri_out = 0;
    always #1 tri_out = 4'bz;

    // MIV_RV32IMA_L1_AHB_C0_MIV_RV32IMA_L1_AHB_C0 to prevent I/O buffer insertion

endmodule

