module TopModule (
  input in,
  output out
);
  parameter COUNT = "100";
  parameter START = 1'b0;
  parameter STOP = 1'b1;

  wire [1:0] state;
  localparam [1:0] INIT = 2'b00,
                   END1 = 2'b01,
                   END2 = 2'b10;

  reg [1:0] current_state, next_state;
  reg [1:0] prev;

  // State register and previous value tracking
  always @(posedge in) begin
    current_state <= next_state;
    prev <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      INIT: next_state = out ? (prev == STOP) : END1;
      END1: next_state = out ? (prev == STOP) : END2;
      END2: next_state = out ? (prev == INIT) : END1;
      default: next_state = INIT;
    endcase
  end

  // Output logic (Mealy)
  assign out = (current_state == INIT) ? prev :
                 (current_state == END1 || current_state == END2) ? prev[1] :
                 1'b0;

  // State initialization
  initial begin
    current_state = INIT;
  end
endmodule

