  wire [3:0] right_x_check_ge_half_width_plus1 = right_x_check >= (half_width_plus1 + 4'd1);
  wire [3:0] right_x_check_le_half_width_plus1 = right_x_check <= (half_width_plus1 + 4'd1);
  wire right_condition = (right_x_check_ge_half_width_plus1 || right_x_check_le_half_width_plus1);

  wire [3:0] right_x = right_condition ? right_x : 4'd0;

  wire [3:0] right_y = right_x;
  wire [3:0] left_x = right_x;
  wire [3:0] left_x_plus_1 = left_x + 1;

  wire [3:0] left_y_min = Y_MIN + left_x;
  wire [3:0] left_y_max = Y_MAX + left_x;
