module TopModule (
  input x3,
  input x2,
  input x1,
  output f
);
  parameter [7:0] EXPECTED_WIDTH = 8'd0;
  parameter [31:0] WIDTH = 32'd0;

`ifdef USE_MIV_RV32IMA_L1_AHB
  reg [31:0] mem [0:1<<7-1]; // 128-entry 32-bit memory

  // AHB-L Interface Implementation
  wire [31:0] addr = {24'h0, x1[7:0]}; // Convert 8-bit address to byte
  wire [31:0] addr_sefunmi = addr; // Address selection
  wire [31:0] addr_sefunmi_add1 = addr_sefunmi + 32'h4; // Address+4

  // Write Address Channel (WAC)
  wire [31:0] wac_address = addr_sefunmi;
  wire [7:0] wac_data = x3; // Write data from x3[7:0]

  // Write Data Channel (WDC)
  wire [31:0] wac_sefunmi_add1 = wac_data * 32'h4; // Write data *4

  // Write System Channel (WSC)
  reg [31:0] wsc_wdata;
  always @(*) begin
    wsc_wdata = wac_sefunmi_add1; // Write data from WAC
  end

  // Write System Interface (WSI)
  reg [31:0] wsi_wdata;
  always @(*) begin
    wsi_wdata = wsc_wdata; // Write data from WSC
  end

  // Write Operations (example: write to memory)
  integer i;
  always @(x2) begin
    if (x2) begin
      for (i=0; i<(wsi_wdata[31:24] >> 2); i=i+1) begin
        mem[i] <= wsi_wdata[31:2]; // Write 30:2 into consecutive entries
      end
    end
  end

  // Read Operations (example: read first byte)
  wire [31:0] rsc_address = wsc_address; // Address from WSC
  wire [31:0] rsc_sefunmi = rsc_address; // Address selection

  // Read System Channel (RSC)
  reg [31:0] rsc_address_sefunmi;
  always @(*) begin
    rsc_address_sefunmi = rsc_address; // Address from RSC
  end

  // Read System Interface (RSI)
  reg [31:0] rsi_rdata;
  reg [31:0] rsi_raddr_sefunmi;
  reg [31:0] rsi_rdata_sefunmi;
  reg [31:0] rsi_raddr_sefunmi_add1;

  always @(*) begin
    rsi_raddr_sefunmi_add1 = rsi_raddr_sefunmi + 32'h4; // Address+4
  end

  // Read Operations (example: read first byte)
  wire [31:0] rsi_addr_sefunmi = rsi_raddr_sefunmi;
  wire [31:0] rsi_addr_sefunmi_add1 = rsi_addr_sefunmi + 32'h4;

  integer j;
  reg [31:0] rsi_rdata_sefunmi_comb;
  always @(*) begin
    rsi_rdata_sefunmi_comb = 32'h0;
    for (j=0; j<128; j=j+1) begin
      rsi_rdata_sefunmi_comb[j] = mem[j][rsi_addr_sefunmi_comb[7:0]] + 1;
    end
  end

  // Update AHB-L Interface (example assignments)
  assign rsi_rdata = rsi_rdata_sefunmi_comb;
  assign rsi_rdata_sefunmi = rsi_rdata_sefunmi_comb;

  // Write to f (example: lower 8 bits of read data)
  assign f = rsi_rdata_sefunmi[7:0];

`else
  // Synthesis directives for black box IP
  `ifndef USE_MIV_RV32IMA_L1_AHB
  `endif
`endif

endmodule

module TopModule (
  input [3:0] x,
  output logic f
);
  localparam S0 = 4'd0;
  localparam S1 = 4'd1;
  localparam S2 = 4'd2;
  localparam S3 = 4'd3;
  localparam S4 = 4'd4;
  localparam S5 = 4'd5;
  localparam S6 = 4'd6;
  localparam S7 = 4'd7;
  localparam S8 = 4'd8;

  reg [3:0] current_state = S0;

  always @(x) begin
    case (x)
      4'h0: current_state <= S0;
      4'h1: current_state <= S1;
      4'h2: current_state <= S2;
      4'h3: current_state <= S3;
      4'h4: current_state <= S4;
      4'h5: current_state <= S5;
      4'h6: current_state <= S6;
      4'h7: current_state <= S7;
      4'h8: current_state <= S8;
      default: current_state <= S0;
    endcase
  end

  assign f = (current_state == S8);

endmodule

